/* ChinaLowCost connected design prototype. Local sample data only. No network calls. */
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => '₦' + Number(n).toLocaleString('en-NG', {maximumFractionDigits:0});
const products = [
 {id:'FAN-01',name:'Rechargeable desk fan',category:'Electronics',art:'fan',retail:5000,bulk:4500,volume:4000,moq:10,pack:5,variant:'Sage',tag:'Wholesale favourite'},
 {id:'LMP-02',name:'Minimal table lamp',category:'Home & living',art:'lamp',retail:8500,bulk:7200,volume:6500,moq:10,pack:5,variant:'Sand',tag:'Home collection'},
 {id:'BTL-03',name:'Everyday insulated bottle',category:'Everyday essentials',art:'bottle',retail:3200,bulk:2700,volume:2300,moq:10,pack:5,variant:'Mist',tag:'Everyday value'},
 {id:'SPK-04',name:'Portable wireless speaker',category:'Electronics',art:'speaker',retail:12000,bulk:10500,volume:9500,moq:10,pack:5,variant:'Clay',tag:'Tech collection'}
];
const initialState = () => ({mode:'wholesale',selected:'FAN-01',qty:55,cart:[],quote:null,address:{name:'Ada · sample customer',street:'Sample delivery address',area:'Ikeja',phone:'Demo contact'},paid:false,transfer:false,order:false,consent:false,draft:{title:'Rechargeable desk fan',sku:'FAN-01',pack:'5',moq:'10',cost:'3200'},draftSubmitted:false,staffStatus:'Pending approval',catalogStatus:'Pending review',approvals:[],audit:[],messages:[],returnRequested:false,cashCollected:false,cashReconciled:false,delivery:false,inspection:false,pickup:false,dispatch:false,marketing:false,staffActor:'Manager',sync:false,quoteAccepted:false});
let state = initialState();
try{const saved=JSON.parse(localStorage.getItem('clc-prototype-v3'));if(saved)state={...state,...saved};}catch{}
let route='C02',scenario='normal',category='All finds',searchTerm='',localImage='',imageName='',uploadedVideo=false,videoFrame=0,toastTimer;
const persist=()=>{try{localStorage.setItem('clc-prototype-v3',JSON.stringify(state));}catch{}};
const record=(action)=>{state.audit.unshift({action,actor:state.staffActor,time:new Date().toLocaleTimeString('en-GB')});persist();};
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4200);}
function go(id){if(!PAGES.some(p=>p.ID===id))return;scenario='normal';if(location.hash==='#'+id)render();else location.hash=id;}
function art(p,cls=''){return `<svg class="${cls}" role="img" aria-label="${esc(p.name)} illustration"><use href="#${p.art}"/></svg>`;}
function badge(text,kind=''){return `<span class="badge ${kind}">${esc(text)}</span>`;}
function link(id,text,cls=''){return `<a class="${cls}" href="#${id}">${text}</a>`;}
function button(text,action,cls='',disabled=false){return `<button class="${cls}" onclick="${action}" ${disabled?'disabled':''}>${text}</button>`;}
function note(text,kind=''){return `<div class="notice ${kind}">${text}</div>`;}
function card(title,body){return `<div class="card">${title?`<h3>${title}</h3>`:''}${body}</div>`;}
function field(id,label,value='',type='text',extra=''){return `<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${extra}>`;}
function select(id,label,options,value){return `<label for="${id}">${label}</label><select id="${id}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function row(label,value){return `<div class="row"><span>${label}</span><strong>${value}</strong></div>`;}
function stats(items){return `<div class="grid four">${items.map(([label,value,sub])=>`<div class="card stat"><small>${label}</small><div class="number">${value}</div><p>${sub}</p></div>`).join('')}</div>`;}
function timeline(items){return `<ol class="timeline">${items.map(([title,sub,pending])=>`<li class="${pending?'pending':''}"><strong>${title}</strong><small>${sub}</small></li>`).join('')}</ol>`;}
function links(items){return `<div class="link-list">${items.map(([id,title])=>link(id,`${title}<span>↗</span>`)).join('')}</div>`;}
function mini(p,sub){return `<div class="mini-product">${art(p)}<div><strong>${p.name}</strong><p>${esc(sub||p.id+' · '+p.variant)}</p></div></div>`;}
function form(title,body,action,label='Save sample changes'){return card(title,`<form onsubmit="event.preventDefault();${action}">${body}<div class="form-actions">${button(label,'this.form.requestSubmit()') /* button is made non-submit below */}</div></form>`).replace(/<button /g,'<button type="button" ');}
function primaryForm(title,body,handler,label){return card(title,`<form onsubmit="event.preventDefault();${handler}">${body}<div class="form-actions"><button type="submit">${label}</button></div></form>`);}
function picked(){return products.find(p=>p.id===state.selected)||products[0];}
function rate(p,q,mode=state.mode){return mode==='retail'?p.retail:q>=50?p.volume:p.bulk;}
function validQty(p,q,mode=state.mode){return Number.isSafeInteger(q)&&q>0&&q<=100000&&(mode==='retail'||q>=p.moq&&q%p.pack===0);}
function totals(){let goods=state.cart.reduce((sum,l)=>sum+l.qty*rate(products.find(p=>p.id===l.sku),l.qty,l.mode),0);return {goods,delivery:goods?8000:0,total:goods?goods+8000:0};}
function orderSummary(){const t=totals();return row('Goods subtotal',money(t.goods))+row('Delivery · sample flat fee',money(t.delivery))+row('Tax','Not configured for demo')+'<hr class="divider">'+row('Order total',`<span class="amount">${money(t.total)}</span>`);}
function heading(title,desc='',actions=''){return `<div class="pagehead"><div><h1 tabindex="-1" id="page-title">${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
const customerNames={C01:'Welcome to ChinaLowCost',C02:'Discover something better',C03:'Shop the collection',C04:'Search our catalog',C05:'Find it with a photo',C06:'Similar products',C07:'Product details',C08:'Wholesale calculator',C09:'Your quotations',C10:'Shopping cart',C11:'Where should we deliver?',C12:'Review your order',C13:'Choose how to pay',C14:'Transfer & pay on delivery',C15:'Your orders',C16:'Follow your delivery',C17:'See it. Know it. Shop it.',C18:'We’re here to help',C19:'Returns & resolutions',C20:'Your account',C21:'Receipts & refunds'};
const workerNames={W01:'Your staff access',W02:'Today’s assignments',W03:'Supplier visit',W04:'Capture product content',W05:'Review AI suggestions',W06:'Build a catalog draft',W07:'Confirm availability',W08:'Supplier pickup',W09:'Inspect the goods',W10:'Pack & dispatch',W11:'Delivery assignments',W12:'Confirm delivery',W13:'Cash collection',W14:'Return pickup',W15:'Profile & sync queue'};
const adminGroups=[['Workspace',['A01','A26']],['People & partners',['A02','A03','A04','A05','A06']],['Catalog & content',['A07','A08','A09','A10','A24','A25']],['Sales & operations',['A11','A12','A13','A14','A15','A16','A21','A22','A23']],['Finance',['A17','A18','A19','A20','A27']],['System',['A28','A29','A30']]];
function navLabel(p){return ({A01:'Overview',A02:'Staff approvals',A03:'Roles & access',A04:'Suppliers',A05:'Banking & terms',A06:'Visits & assignments',A07:'Products & variants',A08:'Catalog review',A09:'Pricing',A10:'Stock & reservations',A11:'Quotations',A12:'Orders',A13:'Purchase orders',A14:'Goods receipts',A15:'Dispatch board',A16:'Delivery incidents',A17:'Payments',A18:'Cash reconciliation',A19:'Refunds',A20:'Supplier settlements',A21:'Returns',A22:'Customers & support',A23:'WhatsApp inbox',A24:'Video library',A25:'AI review',A26:'Approval center',A27:'Reports & ledger',A28:'Business settings',A29:'Audit trail',A30:'Integration health'})[p.ID]||workerNames[p.ID]||customerNames[p.ID];}
function shell(content,page){const app=page.Application;const isCustomer=app==='Customer';const roleSelect=`<select aria-label="Preview application" onchange="go(this.value)"><option value="C02" ${isCustomer?'selected':''}>Customer app</option><option value="W02" ${app==='Worker'?'selected':''}>Worker app</option><option value="A01" ${app==='Admin'?'selected':''}>Admin dashboard</option></select>`;
const preview=`<div class="top-preview"><span>INTERACTIVE PROTOTYPE &nbsp; · &nbsp; Sample data only <span class="hide-mobile">· No live transactions</span></span><div class="preview-controls">${roleSelect}<select class="state-control" aria-label="Preview screen state" onchange="scenario=this.value;render()">${['normal','empty','error','offline'].map(s=>`<option ${scenario===s?'selected':''}>${s}</option>`).join('')}</select>${button('All 66 pages','openPageMap()')}${button('Reset demo','resetDemo()')}</div></div>`;
const brand=link('C02','<span class="brandmark">c</span>china<b>lowcost</b>.','brand');
const top=`<header class="topbar">${brand}${isCustomer?`<form class="header-search" onsubmit="event.preventDefault();searchTerm=$('global-search').value;go('C04')"><input id="global-search" aria-label="Search catalog" placeholder="Find products for your home or business" value="${esc(searchTerm)}"><button type="submit" aria-label="Search">⌕</button><button type="button" class="secondary" aria-label="Search by photo" onclick="go('C05')">▧</button></form><div class="toplinks">${link('C09','Quotations')}${link('C10',`Cart <b>(${state.cart.reduce((n,l)=>n+l.qty,0)})</b>`)}${link('C20','<span class="avatar">AD</span><span class="label"> &nbsp;Account</span>')}</div>`:`<div class="toplinks"><span class="muted">${app==='Worker'?'Field operations · sample staff':'Central operations · sample manager'}</span><span class="avatar">${app==='Worker'?'CW':'OM'}</span></div>`}</header>`;
const navigation=isCustomer?`<nav class="shopnav" aria-label="Customer navigation"><div class="links">${[['C02','Discover'],['C03','Categories'],['C17','Videos'],['C15','Orders'],['C18','Support']].map(([id,t])=>link(id,t,route===id?'active-link':'')).join('')}</div><div class="mode-switch" aria-label="Shopping mode">${['retail','wholesale'].map(m=>button(m==='retail'?'Retail':'Wholesale',`setMode('${m}')`,state.mode===m?'selected':'')).join('')}</div></nav>`:'';
const workPages=PAGES.filter(p=>p.Application===app);const sidebar=isCustomer?'':`<aside aria-label="${app} navigation">${(app==='Admin'?adminGroups:[['Field workspace',workPages.map(p=>p.ID)]]).map(([group,ids])=>`<div class="eyebrow">${group}</div>${ids.map(id=>{const p=PAGES.find(x=>x.ID===id);return link(id,`<span class="side-icon">${app==='Worker'?'◈':'▦'}</span>${navLabel(p)}`,route===id?'active':'');}).join('')}`).join('')}</aside>`;
const mobile=isCustomer?'':`<div class="mobile-menu"><label for="mobile-page">${app} pages</label><select id="mobile-page" onchange="go(this.value)">${workPages.map(p=>`<option value="${p.ID}" ${p.ID===route?'selected':''}>${p.ID} · ${navLabel(p)}</option>`).join('')}</select></div>`;
const footer=`<footer class="footer"><span><strong>ChinaLowCost</strong> · Thoughtfully sourced. Locally delivered.</span><span>Sample products, prices and records. Suppliers have no logins.</span></footer>`;
return preview+top+navigation+mobile+`<div class="${isCustomer?'':'workspace'}">${sidebar}<main id="content" class="${isCustomer?'customer-main':'work-main'}"><div class="crumb">${link(isCustomer?'C02':app==='Worker'?'W02':'A01',app==='Admin'?'Admin':app+' app')} &nbsp;/&nbsp; ${esc(navLabel(page))}</div>${content}<div class="screen-meta">${page.ID} · ${esc(page.Screen)} · ${esc(page.Access)} · ${esc(page['Key states'])}</div>${footer}</main></div>`;
}
function render(){route=location.hash.slice(1)||'C02';const page=PAGES.find(p=>p.ID===route);if(!page){location.hash='C02';return;}let content=page.Application==='Customer'?customerPage(route):page.Application==='Worker'?workerPage(route):adminPage(route);if(scenario==='empty')content=heading(navLabel(page),'An empty-state preview for this page.')+`<div class="empty"><div class="symbol">◇</div><h2>Nothing here yet</h2><p>${page.Application==='Customer'?'Your saved items and activity will appear here. Explore the collection to begin.':'New records will appear when the relevant task or request is created.'}</p>${button('Restore sample records',"scenario='normal';render()")}</div>`;if(scenario==='error')content=heading(navLabel(page))+note('This is a simulated service error. Your current demo data is preserved.','error')+card('We couldn’t load this page',`<p>Please try again or contact support if the issue continues.</p>${button('Try again',"scenario='normal';render()")}`);if(scenario==='offline')content=note('Offline preview: viewing saved sample records. External actions will need a connection in the live application.','warn')+content;$('app').innerHTML=shell(content,page);document.title=navLabel(page)+' · ChinaLowCost';}
function setMode(mode){state.mode=mode;state.qty=mode==='retail'?1:55;persist();render();}
function productCards(list=products){return `<div class="products">${list.map(p=>`<article class="product"><a href="#C07" onclick="state.selected='${p.id}';persist()"><div class="product-art"><span class="product-tag">${p.tag}</span>${art(p)}</div></a><div class="product-info"><small>${p.category.toUpperCase()} · ${p.id}</small><h3><a href="#C07" onclick="state.selected='${p.id}';persist()">${p.name}</a></h3><div class="price">${money(state.mode==='wholesale'?p.volume:p.retail)}${state.mode==='wholesale'?'<small> / unit*</small>':''}</div><small>${state.mode==='wholesale'?`*50+ units · MOQ ${p.moq} · packs of ${p.pack}`:'Retail price · 1 unit minimum'}</small>${button('View product &nbsp; ↗',`state.selected='${p.id}';persist();go('C07')`,'secondary')}</div></article>`).join('')}</div>`;}
function catalog(){const cats=['All finds','Home & living','Electronics','Everyday essentials'];const list=products.filter(p=>(category==='All finds'||category===p.category)&&p.name.toLowerCase().includes(searchTerm.toLowerCase()));return `<div class="chips">${cats.map(c=>button(c,`category='${c}';render()`,category===c?'selected':'')).join('')}</div><div class="row"><span>${list.length} products · Sample catalog</span><span>Availability confirmed before payment</span></div>`+(list.length?productCards(list):`<div class="empty"><h2>No matching products</h2><p>Try a broader search or ask our team for help.</p>${button('Clear filters',"category='All finds';searchTerm='';render()")}</div>`);}
function customerPage(id){const p=picked();switch(id){
case 'C01':return `<div class="auth">${heading('Good finds start here.','Create your customer account or sign in to continue.')}${primaryForm('Sign in with your phone',field('phone','Phone number (sample only)','08000000000','tel','required pattern="[0-9+ ]{8,16}"')+note('Demo verification code: <strong>123456</strong>. No SMS will be sent.')+field('otp','Verification code','','text','required pattern="123456" inputmode="numeric" maxlength="6"')+'<p class="muted">Use sample details. This prototype does not authenticate real accounts.</p>',"toast('Demo phone verified. Welcome, Ada.');go('C02')",'Verify & continue')}${link('C02','Continue browsing without signing in →')}</div>`;
case 'C02':return `<div class="hero"><div class="hero-copy"><div class="eyebrow">For your home. For your next big idea.</div><h1>Small prices.<br>Big possibilities.</h1><p>Discover everyday essentials and business-ready goods from Chinese suppliers right here in Nigeria.</p><div class="actions">${link('C03','Explore the collection &nbsp; ↗','button')}${link('C08','Buy wholesale','button secondary')}</div><small>One trusted team. Retail finds. Wholesale value.</small></div><div class="hero-art">${art(products[0])}<div class="floating">EVERYDAY COMFORT<strong>Rechargeable desk fan</strong><span>From ₦4,000/unit · 50+ units</span></div></div></div><div class="trustrow"><div><strong>01 &nbsp; Clear wholesale pricing</strong><span>See quantity tiers, pack sizes and order minimums.</span></div><div><strong>02 &nbsp; Real product stories</strong><span>Discover goods through staff-captured product content.</span></div><div><strong>03 &nbsp; From pickup to doorstep</strong><span>ChinaLowCost manages your order and delivery.</span></div></div><div class="section-head"><h2>Find your next best seller</h2>${link('C03','View collection ↗')}</div>${productCards()}<div class="banner"><div><div class="eyebrow">A closer look</div><h2>Watch it. Know it. Shop it.</h2><p>Product stories from our team on the ground.</p></div>${link('C17','Explore video shopping &nbsp; ▶','button lime')}</div>`;
case 'C03':return heading('Good finds for every kind of buyer.','Explore a small sample collection. Switch retail and wholesale in the navigation.')+catalog();
case 'C04':return heading('Find your next good find.','Search by product name or start with a photo.')+card('',`<form class="header-search" style="max-width:none" onsubmit="event.preventDefault();searchTerm=$('catalog-query').value;render()"><input id="catalog-query" aria-label="Product name" placeholder="Try fan, bottle or lamp" value="${esc(searchTerm)}"><button type="submit">Search</button>${link('C05','Use a photo','button secondary')}</form>`)+catalog();
case 'C05':return heading('Have a picture? Start there.','Find similar products from the ChinaLowCost catalog.')+`<div class="split">${card('',`<div class="dropzone"><div class="symbol">▧</div><h2>Choose a product photo</h2><p>JPG, PNG or WebP · up to 10 MB</p><label for="photo-upload">Select image from your device</label><input id="photo-upload" type="file" accept="image/jpeg,image/png,image/webp" onchange="chooseImage(this)">${localImage?`<img class="image-preview" src="${esc(localImage)}" alt="Your selected product photo">`:''}</div><label class="check"><input id="image-consent" type="checkbox" required> I have permission to use this image.</label><div class="actions">${button('Preview similar matches',"if(!$('image-consent').checked){toast('Confirm image permission first.');return;}go('C06')")}${button('Use sample photo',"localImage='';imageName='Sample desk fan';go('C06')",'secondary')}</div>`)}${card('How photo discovery works',timeline([['Choose a photo','Focus on one item and use good lighting.'],['Explore similar products','AI will search only the published catalog.'],['Check the exact details','Confirm variant, dimensions and pack size before ordering.']])+note('The preview uses curated sample matches. No AI service runs and your image stays in this browser.'))}</div>`;
case 'C06':return heading('A few possibilities for your photo.','Curated demonstration matches. Similarity does not guarantee the same product.',link('C05','Try another photo','button secondary'))+note('Sample results · AI photo matching is simulated. No similarity score is invented.')+(localImage?card('Your search image',`<img class="image-preview" src="${esc(localImage)}" alt="Uploaded search image">`):'')+productCards()+`<div class="banner"><div><h3>Not quite the right product?</h3><p>Our team can help you check the details.</p></div>${link('C18','Ask our team','button lime')}</div>`;
case 'C07':return heading(p.name,p.category+' · '+p.id)+`<div class="split"><div><div class="detail-art">${art(p)}</div>${card('A closer look',`<p>Illustrative product content. Color, dimensions and performance claims must be verified by staff before publication.</p>${link('C17','Watch product story →')}`)}</div>${card('',`${badge('Staff confirmation required','warn')}<h2 style="margin-top:20px">${p.name}</h2><div class="amount">${money(rate(p,state.qty))}<small> / unit</small></div><p>${state.mode==='wholesale'?'Wholesale pricing depends on your quantity.':'Retail shopping · no wholesale minimum.'}</p>${select('variant','Variant',[p.variant],p.variant)}${field('product-qty','Quantity in units',state.qty,'number','min="1" max="100000" required')}<p class="muted">Wholesale MOQ ${p.moq} · pack multiple ${p.pack}. Tiers apply separately to each variant.</p>${table(['Quantity','Per unit'],[['10–49 units',money(p.bulk)],['50+ units',money(p.volume)]])}<div class="form-actions">${button('Add to cart',"addCart(Number($('product-qty').value))")}${button('Calculate / get quotation',"state.qty=Number($('product-qty').value);persist();go('C08')",'secondary')}</div><div id="quantity-error" class="form-error" role="status"></div><hr class="divider"><p class="muted">Delivery fee is confirmed at checkout. ChinaLowCost handles supplier pickup and customer support.</p>${link('C18','Ask a question →')}`)}</div>`;
case 'C08':return heading('Buy more. Plan smarter.','Compare quantity tiers and create a quotation with a clear cost breakdown.')+`<div class="split">${card('Build your wholesale quantity',`${mini(p)}${select('calc-product','Product',products.map(x=>x.name),p.name)}${field('calc-qty','Quantity in units',state.qty,'number','min="10" max="100000" step="5"')}<p class="muted">MOQ 10 · packs of 5 · All-units pricing for each variant.</p>${table(['Quantity','Unit price','Your benefit'],[['10–49',money(p.bulk),'Wholesale rate'],['50+ units',money(p.volume),'Volume rate']])}<div class="form-actions">${button('Update calculation','calculateWholesale()')}${button('Try 50 units',"$('calc-qty').value=50;calculateWholesale()",'secondary')}</div><p id="calc-error" class="form-error" role="status"></p>`)}${card('Your cost breakdown',`<div id="calc-summary">${calculation(p,state.qty)}</div>${note('Sample delivery fee ₦8,000. Tax is not configured. Staff must confirm availability and final delivery before payment.')}<div class="actions">${button('Create quotation','createQuote()')}${button('Add quantity to cart',`addCart(state.qty,true)`,'secondary')}</div>`)}</div>`;
case 'C09':return quotePage();
case 'C10':return heading('Your next good finds.','Prices are calculated for each product and quantity.',link('C03','Continue shopping','button secondary'))+(state.cart.length?`<div class="split">${card('Items in your cart',table(['Product','Quantity','Line total',''],state.cart.map((l,i)=>{const x=products.find(p=>p.id===l.sku);return [mini(x,l.mode+' · '+x.variant),`${l.qty} units<small>${money(rate(x,l.qty,l.mode))} / unit</small>`,money(l.qty*rate(x,l.qty,l.mode)),button('Remove',`state.cart.splice(${i},1);persist();render()`,'ghost')];})))}${card('Order summary',orderSummary()+link('C11','Choose delivery address &nbsp; →','button')+note('Final stock and delivery confirmation are required before real payment.'))}</div>`:`<div class="empty"><div class="symbol">▱</div><h2>Your cart is ready for something good.</h2><p>Choose a product or calculate a wholesale quantity to begin.</p>${link('C03','Explore products','button')}</div>`);
case 'C11':return heading('A destination for your good finds.','The pilot delivery zone in this prototype is Lagos only.')+checkoutSteps(1)+`<div class="split">${primaryForm('Delivery details',`<div class="form-grid">${field('address-name','Recipient name',state.address.name,'text','required')}${field('address-phone','Contact (use sample data)',state.address.phone,'text','required')}</div>${field('address-street','Street address',state.address.street,'text','required')}${select('address-area','Area',['Ikeja','Lekki','Yaba','Outside pilot zone'],state.address.area)}${note('Use fictional details in the preview. No address is sent to any service.')}`,"saveAddress()",'Save & review order')}${card('Delivery information',row('City','Lagos · sample pilot')+row('Sample delivery fee',money(8000))+row('Delivery timing','Confirmed after supplier pickup')+note('Orders outside the pilot zone need a staff quotation.','warn'))}</div>`;
case 'C12':return heading('Everything in one clear view.','Review items, delivery and the amount before proceeding.')+checkoutSteps(2)+(state.cart.length?`<div class="split">${card('Items & destination',state.cart.map(l=>mini(products.find(p=>p.id===l.sku),l.qty+' units · '+l.mode)).join('<hr class="divider">')+'<hr class="divider">'+row('Recipient',esc(state.address.name))+row('Delivery',esc(state.address.street+', '+state.address.area))+link('C11','Edit address →'))}${card('Final review',orderSummary()+`<label class="check"><input id="checkout-consent" type="checkbox"> I confirm this sample order and understand that live availability and terms require staff confirmation.</label><div class="form-actions">${button('Continue to payment',"if(!$('checkout-consent').checked){toast('Please confirm the order review.');return;}state.order=true;persist();go('C13')")}</div>`)}</div>`:note('Your cart is empty. '+link('C03','Choose products to preview checkout.')));
case 'C13':return heading('Your payment, clearly handled.','A safe design preview: no card or bank credentials are requested.')+checkoutSteps(3)+`<div class="split">${card('Payment method',`${note('No real money moves in this prototype. The live app must use a verified provider response.','warn')}<label class="option-card"><input type="radio" name="method" checked> <strong>Hosted checkout</strong><small>Payment details would be entered with the payment provider.</small></label><div class="form-actions">${button('Simulate verified payment','simulatePayment()', '',!state.cart.length)}${link('C14','Bank transfer / COD','button secondary')}</div>${button('Preview failed payment',"toast('Simulated payment failure. No funds were collected. You can retry.')",'ghost')}`)}${card('Amount to pay',orderSummary()+row('Status',badge(state.paid?'Verified demo payment':'Awaiting payment',state.paid?'':'warn')))}</div>`;
case 'C14':return heading('Alternative payment options.','Funds are confirmed by finance, never by screenshots alone.')+`<div class="grid">${primaryForm('Bank transfer reference',note('No real bank account is provided. Enter a fictional reference only.')+field('transfer-reference','Sample payment reference','DEMO-TRANSFER-001','text','required')+row('Status',badge(state.transfer?'Awaiting finance verification':'Not reported','warn')),"state.transfer=true;record('Sample transfer reported');toast('Reference saved for finance verification. Order is not marked paid.');render()",'Report sample transfer')}${card('Pay on delivery',badge('Approval required','warn')+`<p>Eligibility depends on delivery zone, order value and staff approval. Collecting cash and reconciling it are separate steps.</p>${row('Order amount',money(totals().total))}${button('Request COD review',"record('Customer requested sample COD review');toast('COD request added to the demo review queue. No approval has been granted.')",'',!state.cart.length)}<div class="form-actions">${link('C13','Return to payment options','button secondary')}</div>`)}</div>`;
case 'C15':return heading('Every order, at a glance.','Track your current purchase or revisit a past order.')+stats([['Active orders',state.order?'1':'0','Your demo checkout'],['Completed','1','Historical sample order'],['Quotes',state.quote?'1':'0','Created in this preview'],['Return requests',state.returnRequested?'1':'0','Sample case']])+card('Order history',table(['Order','Items','Total','Status',''],[...(state.order?[[`CLC-DEMO-001<small>Current sample order</small>`,(state.orderSnapshot?.units??state.cart.reduce((n,l)=>n+l.qty,0))+' units',money(state.orderSnapshot?.total??totals().total),badge(state.paid?'Confirmed':'Awaiting payment',state.paid?'':'warn'),link('C16','Track order ↗')]]:[]),['CLC-DEMO-000<small>Historical sample · delivered</small>','10 desk fans',money(53000),badge('Delivered'),link('C19','Request return ↗')]]))+card('Order actions',links([['C16','View tracking demonstration'],['C21','Receipts & refund history'],['C18','Contact support']]));
case 'C16':return trackingPage();
case 'C17':return heading('See the details that matter.','Product stories captured by ChinaLowCost staff.')+`<div class="split">${card('',`<div class="video-stage">${art(p)}<div><p id="video-caption">Product story · ${p.name}</p>${button('▶','playStory()','',false)}</div></div><div class="progress"><span id="video-progress" style="width:${videoFrame*33}%"></span></div><p class="muted">Interactive storyboard only. No real product footage is included.</p>`)}${card('Shop this story',mini(p)+row('Retail price',money(p.retail))+row('Wholesale MOQ',p.moq+' units')+note('Linked product details use current catalog pricing. A video never guarantees stock.')+`<div class="actions">${link('C07','View product','button')}${link('C08','Calculate wholesale','button secondary')}</div>`)}</div><div class="section-head"><h2>More product stories</h2></div>${productCards()}`;
case 'C18':return heading('A real team behind every order.','Ask about a product, quotation, delivery or return.')+`<div class="split">${chat('Customer support','support')}${card('Ways we can help',links([['C16','Track a shipment'],['C09','Review a quotation'],['C19','Request a return']])+note('WhatsApp handoff is simulated. No message is sent outside this prototype.')+button('Preview WhatsApp handoff',"openModal('Continue with WhatsApp', '<p>The live application would open an official ChinaLowCost conversation with your permission and a scoped order link.</p><p>No WhatsApp account or number is connected to this preview.</p>')",'secondary'))}</div>`;
case 'C19':return heading('Let’s resolve it together.','Return requests remain linked to delivered items and their payment records.')+`<div class="split">${primaryForm('Request a return',row('Eligible sample order','CLC-DEMO-000 · delivered')+select('return-reason','Reason',['Damaged on arrival','Wrong variant','Not as described'],'Damaged on arrival')+field('return-qty','Units to return',1,'number','required min="1" max="10"')+'<label for="return-note">What happened?</label><textarea id="return-note" required placeholder="Describe the issue using sample information"></textarea>'+note('No refund is issued automatically. Inspection and independent finance approval are required.'),"state.returnRequested=true;record('Sample return requested');toast('Return request saved. Inspection is pending.');render()",'Submit return request')}${card('Case progress',timeline([['Request',state.returnRequested?'Sample case RET-001 received':'No current request'],['Inspection','Our team reviews the item',true],['Resolution','Replacement or approved refund',true]])+link('C18','Contact support →'))}</div>`;
case 'C20':return heading('Your account. Your preferences.','Business details, delivery information and communication choices.')+`<div class="grid">${primaryForm('Profile & preferences',field('profile-name','Display name',state.address.name,'text','required')+field('business-name','Business name (optional)','Ada Home Store')+`<label class="check"><input id="marketing" type="checkbox" ${state.marketing?'checked':''}> Receive optional marketing updates</label><p class="muted">Transactional order updates follow the channel permissions you provide.</p>`,"state.address.name=$('profile-name').value;state.marketing=$('marketing').checked;persist();toast('Sample profile updated.')",'Save preferences')}${card('Your activity',links([['C09','My quotations'],['C15','My orders'],['C11','Delivery addresses'],['C21','Receipts & refunds'],['C18','Privacy or account assistance']]))}</div>`;
case 'C21':return heading('Your financial records.','Verified payments, refunds and downloadable demo receipts.')+card('Receipt history',table(['Reference','Order','Amount','Status',''],[['RCP-DEMO-000','CLC-DEMO-000',money(53000),badge('Historical sample'),button('Download PDF',"downloadDocument('receipt')",'secondary')],...(state.paid?[['RCP-DEMO-001','CLC-DEMO-001',money(state.orderSnapshot?.total??totals().total),badge('Demo payment verified'),button('Download PDF',"downloadDocument('receipt-current')",'secondary')]]:[])]))+card('Refund history',note(state.returnRequested?'RET-001 is awaiting inspection. No refund has been approved.':'No refunds in your sample account.')+link('C19','View return cases →'));
default:throw Error('Missing customer route '+id);
}}
function checkoutSteps(step){return `<div class="flowsteps">${['Cart','Delivery','Review','Payment'].map((s,i)=>`<span class="${i<=step?'on':''}">${i+1}. ${s}</span>`).join('')}</div>`;}
function calculation(p,q){if(!validQty(p,q,'wholesale'))return note('Enter 10 or more units in multiples of 5.','warn');const r=rate(p,q,'wholesale');return row('Quantity',q+' units')+row('Unit rate',money(r))+row('Goods subtotal',money(q*r))+row('Sample delivery',money(8000))+'<hr class="divider">'+`<div class="amount">${money(q*r+8000)}</div><p class="muted">Retail-reference savings: ${money((p.retail-r)*q)}</p>`;}
function calculateWholesale(){const p=products.find(x=>x.name===$('calc-product').value);const q=Number($('calc-qty').value);if(!validQty(p,q,'wholesale')){$('calc-error').textContent='Use a whole quantity of 10–100,000 units in multiples of 5.';return;}state.selected=p.id;state.qty=q;state.mode='wholesale';persist();render();toast('Wholesale calculation updated.');}
function createQuote(){if(!validQty(picked(),state.qty,'wholesale')){toast('Choose a valid wholesale quantity first.');return;}const p=picked();state.quote={id:'Q-DEMO-001',sku:p.id,name:p.name,qty:state.qty,rate:rate(p,state.qty,'wholesale'),delivery:8000,issued:Date.now(),expires:Date.now()+86400000,version:1};state.quoteAccepted=false;persist();go('C09');}
function quotePage(){const q=state.quote;return heading('A clear plan for your next order.','Download, review and accept a versioned quotation.',link('C08','New quotation','button secondary'))+(!q?`<div class="empty"><div class="symbol">▤</div><h2>No quotations yet</h2><p>Use the wholesale calculator to create your first sample quotation.</p>${link('C08','Calculate wholesale','button')}</div>`:`<div class="split">${card('Quotation '+q.id,`${badge(Date.now()>q.expires?'Expired':state.quoteAccepted?'Accepted':'Issued',Date.now()>q.expires?'warn':'')}<p style="margin-top:17px">Version ${q.version} · valid until ${new Date(q.expires).toLocaleString('en-GB')}</p>${table(['Product','Units','Unit rate','Subtotal'],[[esc(q.name),q.qty,money(q.rate),money(q.qty*q.rate)]])}${note('Quotation does not reserve stock. Final availability and delivery confirmation are required.')}<div class="actions">${button('Download quotation PDF',"downloadDocument('quote')")}${button('Accept & add to cart','acceptQuote()','secondary',Date.now()>q.expires||state.quoteAccepted)}</div>`)}${card('Quotation total',row('Goods subtotal',money(q.qty*q.rate))+row('Sample delivery',money(q.delivery))+row('Tax','Not configured')+'<hr class="divider">'+`<div class="amount">${money(q.qty*q.rate+q.delivery)}</div><p class="muted">Version prices are frozen for this sample quotation.</p>${link('C10','View cart →')}`)}</div>`);}
function acceptQuote(){const q=state.quote;if(!q||Date.now()>q.expires){toast('This quote has expired. Create a new version.');return;}if(state.quoteAccepted){toast('This quote is already accepted. View its items in the cart.');go('C10');return;}state.selected=q.sku;state.mode='wholesale';state.qty=q.qty;state.cart=state.cart.filter(l=>!(l.sku===q.sku&&l.mode==='wholesale'));state.cart.push({sku:q.sku,qty:q.qty,mode:'wholesale'});state.quoteAccepted=true;persist();toast('Quote accepted in demo. Items added once. Stock is not reserved.');go('C10');}
function addCart(q,wholesale=false){const p=picked(),mode=wholesale?'wholesale':state.mode;if(!validQty(p,q,mode)){const error=$('quantity-error');if(error)error.textContent=mode==='wholesale'?'Wholesale quantity must be 10–100,000 in multiples of 5.':'Choose a whole quantity from 1–100,000.';toast('Please check the quantity and pack multiple.');return;}const existing=state.cart.find(l=>l.sku===p.id&&l.mode===mode);if(existing){if(existing.qty+q>100000){toast('Maximum demo quantity is 100,000 units per item.');return;}existing.qty+=q;}else state.cart.push({sku:p.id,qty:q,mode});persist();toast('Added to your sample cart.');go('C10');}
function saveAddress(){if($('address-area').value==='Outside pilot zone'){toast('This zone needs a staff delivery quotation.');return;}state.address={name:$('address-name').value,phone:$('address-phone').value,street:$('address-street').value,area:$('address-area').value};persist();go('C12');}
function simulatePayment(){if(!state.cart.length){toast('Add items before previewing payment.');return;}if(state.paid){toast('The demo order is already paid. Reset the sample workspace to start another payment.');go('C15');return;}state.orderSnapshot={...totals(),units:state.cart.reduce((n,l)=>n+l.qty,0),lines:state.cart.map(l=>({...l,unitPrice:rate(products.find(p=>p.id===l.sku),l.qty,l.mode)}))};state.paid=true;state.order=true;record('Simulated provider-verified payment');toast('Demo payment verified. No money was collected.');go('C15');}
function trackingPage(){return heading('Every step, in view.','CLC-DEMO-001 · sample multi-shipment tracking',link('C18','Contact support','button secondary'))+stats([['Order',state.order?'Confirmed demo':'Sample reference','Customer order'],['Payment',state.paid?'Paid':'Pending','Independent financial state'],['Shipment 1',state.delivery?'Delivered':state.dispatch?'Dispatched':'Preparing','30 units · illustrative split'],['Shipment 2','Awaiting pickup','25 units · illustrative split']])+`<div class="grid">${card('Shipment 1 · 30 desk fans',timeline([['Order received','Customer details and quantities recorded'],['Payment verification',state.paid?'Demo provider event verified':'Awaiting verified funds',!state.paid],['Supplier pickup',state.pickup?'Pickup recorded by worker':'Worker pickup pending',!state.pickup],['Dispatch',state.dispatch?'Handover recorded':'Awaiting packing and dispatch',!state.dispatch],['Delivery',state.delivery?'Demo delivery confirmed':'Delivery window to be confirmed',!state.delivery]])+note('This timeline reflects demo actions across worker and admin pages. Shipment quantities illustrate the original 55-unit fan order.'))}${card('Shipment 2 · 25 desk fans',badge('Supplier confirmation pending','warn')+'<p style="margin-top:18px">The second pickup has its own timeline. ChinaLowCost will contact the customer if the delivery window changes.</p>'+row('Delivery window','Not yet confirmed')+row('Latest update','Supplier preparing remaining units')+note('No live courier map or location is connected.'))}</div>`;}
function chat(title,kind){return card(title,`<div class="message"><strong>ChinaLowCost team</strong><br>Welcome! How can we help with your products or order?<small>Sample conversation</small></div>${state.messages.filter(m=>m.kind===kind).map(m=>`<div class="message mine">${esc(m.text)}<small>Demo message · saved locally</small></div>`).join('')}<form onsubmit="event.preventDefault();sendMessage('${kind}')"><label for="message-input">Your message (sample information only)</label><textarea id="message-input" required maxlength="1000" placeholder="Ask about availability or your quotation"></textarea><div class="form-actions"><button type="submit">Send demo message</button></div></form>`);}
function sendMessage(kind){const text=$('message-input').value.trim();if(!text)return;state.messages.push({kind,text});persist();render();toast('Saved locally. No external message was sent.');}
function chooseImage(input){const file=input.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10485760){input.value='';toast('Choose a JPG, PNG or WebP image under 10 MB.');return;}if(localImage)URL.revokeObjectURL(localImage);localImage=URL.createObjectURL(file);imageName=file.name;render();toast('Image loaded locally for the preview.');}
function playStory(){videoFrame=(videoFrame+1)%4;const lines=['Product story · introductory view','Frame 1 · front view and finish','Frame 2 · controls and packaging','Frame 3 · check the catalog for current prices'];$('video-caption').textContent=lines[videoFrame];$('video-progress').style.width=(videoFrame*33)+'%';}
function workerPage(id){const titles=workerNames;const intro=heading(titles[id],'Assigned fieldwork · sample staff member Chidi · demo permissions');const taskRows=[['VIS-014','Catalog visit','Example Lagos Trading',badge(state.consent?'Consent recorded':'Consent needed','warn'),link('W03','Open visit ↗')],['PU-021','Supplier pickup','PO-DEMO-001',badge(state.pickup?'Collected':'Ready for pickup'),link('W08','Open pickup ↗')],['DEL-008','Customer delivery','CLC-DEMO-001',badge(state.delivery?'Delivered':'Pending dispatch','warn'),link('W11','Open delivery ↗')]];switch(id){
case 'W01':return intro+`<div class="auth">${card('Staff activation',row('Sample account','Chidi · catalog/field worker')+row('Access status',badge(state.staffStatus,state.staffStatus==='Active'?'':'warn'))+note('This prototype lets you inspect all screens. Production access must be restricted by approved role and task assignment.')+button('Preview staff sign-in',"toast(state.staffStatus==='Active'?'Demo staff session active.':'Staff activation is pending manager approval.');go('W02')")+`<div class="form-actions">${link('A02','Review staff activation in admin →')}</div>`)}</div>`;
case 'W02':return intro+stats([['Tasks today','3','Visit · pickup · delivery'],['Visit consent',state.consent?'Recorded':'Pending','Before content capture'],['Draft status',state.draftSubmitted?'Submitted':'Draft','Requires independent review'],['Sync queue',state.sync?'Clear':'2 drafts','Local prototype records']])+card('Your assignments',table(['Task','Type','Location / reference','Status',''],taskRows));
case 'W03':return intro+`<div class="grid">${card('Visit VIS-014',row('Supplier','Example Lagos Trading')+row('Location','Sample warehouse · Lagos')+row('Purpose','Product content and availability')+row('Contact channel','Staff-managed phone / WhatsApp')+note('Suppliers have no application logins. Record their permission before capturing or publishing media.'))}${primaryForm('Record capture consent',field('consent-contact','Supplier representative (sample)','Example representative','text','required')+`<label class="check"><input id="supplier-consent" type="checkbox" ${state.consent?'checked':''}> Permission to photograph and market these goods has been recorded.</label>`,"state.consent=$('supplier-consent').checked;record('Supplier media permission '+(state.consent?'recorded':'withdrawn'));if(state.consent)go('W04');else toast('Permission not recorded. Capture remains blocked.');",'Save consent & continue')}</div>`;
case 'W04':return intro+`<div class="split">${card('Photos & product clips',!state.consent?note('Capture is blocked until supplier permission is recorded. '+link('W03','Record consent →'),'warn'):`<div class="dropzone"><div class="symbol">▧</div><h3>Capture the product, packaging and variants</h3><label for="catalog-photo">Choose product image</label><input id="catalog-photo" type="file" accept="image/jpeg,image/png,image/webp" onchange="chooseImage(this)">${localImage?`<img class="image-preview" src="${esc(localImage)}" alt="Selected catalog photo">`:''}<label for="catalog-video">Choose product video (local preview)</label><input id="catalog-video" type="file" accept="video/mp4,video/webm" onchange="uploadedVideo=!!this.files.length;toast('Video selection noted locally. No video is uploaded.')"></div><div class="form-actions">${link('W05','Review AI draft','button')}${link('W06','Enter details manually','button secondary')}</div>`)}${card('Capture checklist',timeline([['Product front & back','Keep labeling readable.'],['Variants & packaging','Show unit, pack and any included accessories.'],['Permissions & claims','Do not infer safety certification or performance.']])+note('File selection stays on your device. AI extraction is demonstrated with sample suggestions.'))}</div>`;
case 'W05':return intro+`<div class="grid">${card('Source material',localImage?`<img class="image-preview" src="${esc(localImage)}" alt="Catalog source photo">`:`<div class="detail-art">${art(products[0])}</div>`)}${primaryForm('Suggested draft · human review required',badge('Simulated AI extraction','warn')+field('ai-title','Suggested title',state.draft.title,'text','required')+field('ai-category','Suggested category','Electronics','text','required')+field('ai-pack','Pack multiple — verify with supplier',state.draft.pack,'number','min="1" required')+`<label class="check"><input id="ai-verified" type="checkbox" required> I checked these fields against the product and supplier information.</label>`+note('Stock, cost, warranty and certification cannot be verified from the photo.'),"state.draft.title=$('ai-title').value;state.draft.pack=$('ai-pack').value;record('Human reviewed simulated AI catalog suggestions');go('W06')",'Save reviewed suggestions')}</div>`;
case 'W06':return intro+catalogDraftForm('Submit for catalog review');
case 'W07':return intro+`<div class="grid">${primaryForm('Confirm supplier availability',row('Supplier','Example Lagos Trading')+row('SKU','FAN-01 · Sage')+field('stock-qty','Available units',55,'number','required min="0" max="100000"')+select('stock-source','Confirmation source',['Phone call','WhatsApp','In-person visit'],'In-person visit')+field('stock-reference','Confirmation note','Sample confirmation','text','required'),"record('Staff availability confirmation: '+$('stock-qty').value+' units');toast('Availability confirmation saved in demo.');go('W08')",'Record confirmation')}${card('Availability rules',note('Supplier-reported stock is provisional until verified. Record freshness and expiry in production.')+row('Sample freshness policy','Reconfirm before procurement')+row('Customer promise','Only after allocation confirmation')+link('A10','View reservations in admin →'))}</div>`;
case 'W08':return intro+card('Pickup PU-021 · PO-DEMO-001',row('Supplier','Example Lagos Trading')+row('Product','30 desk fans · Sage')+row('Agreed supplier cost',money(96000))+row('Status',badge(state.pickup?'Collected':'Awaiting pickup',state.pickup?'':'warn'))+note('Count and inspect goods before accepting them. This is a sample purchase order.')+`<div class="actions">${link('W09','Inspect goods','button')}${button('Record pickup',"if(!state.inspection){toast('Complete inspection first.');return;}state.pickup=true;record('Sample supplier pickup recorded');render()",'secondary')}</div>`);
case 'W09':return intro+`<div class="grid">${primaryForm('Inspection record',field('accepted-qty','Accepted units',30,'number','required min="0" max="30"')+field('rejected-qty','Rejected units',0,'number','required min="0" max="30"')+select('inspection-reason','Condition',['Matches order','Damaged units','Wrong variant','Short quantity'],'Matches order')+'<label for="inspection-note">Evidence note</label><textarea id="inspection-note" placeholder="Describe sample inspection"></textarea>',"saveInspection()",'Save inspection')}${card('What to check',timeline([['Variant & count','Match the PO line and packaging.'],['Condition','Separate damaged or incorrect goods.'],['Evidence','Record discrepancies before collection.']])+link('W08','Back to supplier pickup →'))}</div>`;
case 'W10':return intro+`<div class="grid">${card('Shipment SHP-DEMO-001',row('Accepted units',state.inspection?'30 inspected':'Inspection pending')+row('Pickup',state.pickup?'Recorded':'Pending')+row('Dispatch',badge(state.dispatch?'Dispatched':'Not dispatched','warn'))+note('Dispatch requires accepted inspection and a recorded pickup.')+button('Record courier handover',"if(!state.pickup||!state.inspection){toast('Inspection and pickup must be recorded first.');return;}state.dispatch=true;record('Sample shipment dispatched');toast('Dispatch recorded.');render()"))}${primaryForm('Packing checklist',field('package-reference','Package reference','PKG-DEMO-001','text','required')+`<label class="check"><input type="checkbox" required> Correct variants and quantities packed</label><label class="check"><input type="checkbox" required> Package sealed and label checked</label>`,"record('Sample packing checklist completed');toast('Packing checklist saved.')",'Save packing checklist')}</div>`;
case 'W11':return intro+card('Assigned delivery DEL-008',table(['Order','Area','Packages','Status',''],[['CLC-DEMO-001','Ikeja · sample address','1 package',badge(state.delivery?'Delivered':state.dispatch?'Ready for delivery':'Awaiting dispatch','warn'),link('W12','Open delivery ↗')]]))+card('Delivery instructions',row('Recipient','Ada · sample customer')+row('Contact','Demo contact only')+note('No live location tracking or navigation service is connected.')+links([['W12','Record proof of delivery'],['W13','Record cash if assigned COD'],['C16','View customer tracking']]));
case 'W12':return intro+`<div class="grid">${primaryForm('Delivery verification',row('Shipment','SHP-DEMO-001 · 30 units')+field('delivery-otp','Sample customer OTP','','text','required pattern="123456" maxlength="6" inputmode="numeric"')+note('Use <strong>123456</strong> for this demonstration. Dispatch must be recorded first.')+`<label class="check"><input id="delivery-confirm" type="checkbox" required> The sample recipient accepted the package.</label>`,"if(!state.dispatch){toast('Record dispatch before delivery.');return;}state.delivery=true;record('Sample delivery proof recorded');toast('Delivery confirmed in demo.');go('C16')",'Confirm demo delivery')}${card('Failed attempt',`<p>Customer absent, address issue or damaged package? Keep a separate delivery exception.</p>${button('Record failed attempt',"openActionForm('Failed delivery attempt',[['Reason','Customer absent'],['Next step','Contact customer for redelivery']], 'Delivery attempt failed; incident created in demo')",'secondary')}${note('Delivery evidence cannot verify or reconcile cash collection.','warn')}`)}</div>`;
case 'W13':return intro+`<div class="grid">${primaryForm('Collect cash · sample COD order',row('Reference','CLC-COD-DEMO · separate example')+field('cash-amount','Cash received (NGN)',53000,'number','required min="1" max="1000000"')+field('cash-reference','Collection reference','CASH-DEMO-001','text','required')+row('Status',badge(state.cashReconciled?'Reconciled by finance':state.cashCollected?'Collected · unreconciled':'Expected','warn'))+note('This COD example is separate from the online-paid cart. The worker only records collection.'),"state.cashCollected=true;record('Worker recorded sample COD cash collection');toast('Collected cash recorded. Finance must verify handover.');render()",'Record collection')}${card('Handover to finance',`<p>Finance checks actual cash, acknowledges handover and reconciles the amount.</p>${link('A18','Preview finance reconciliation','button secondary')}`)}</div>`;
case 'W14':return intro+primaryForm('Return collection RET-001',row('Customer case',state.returnRequested?'Requested · sample return':'Historical sample collection')+field('return-collected','Units collected',1,'number','required min="1" max="10"')+select('return-condition','Condition',['Packaging intact','Visible damage','Incomplete accessories'],'Visible damage')+field('return-evidence','Evidence note','Sample return packaging checked','text','required')+note('Collection does not approve a refund. Inspection and finance approval remain separate.'),"record('Sample return collected by worker');toast('Return collection recorded for inspection.');go('A21')",'Record returned items');
case 'W15':return intro+stats([['Sample staff','Chidi','Fieldworker'],['Access',state.staffStatus,'Manager activation'],['Queued drafts',state.sync?'0':'2','Local records only'],['Last sync',state.sync?'Demo complete':'Not yet synced','No server connected']])+card('Sync queue',table(['Record','Type','Status',''],[['IMG-DEMO-01','Product image',badge(state.sync?'Synced demo':'Draft','warn'),button('Retry demo sync',"state.sync=true;record('Simulated draft sync');render()",'secondary')],['TASK-DEMO-02','Task evidence',badge(state.sync?'Synced demo':'Queued','warn'),link('W02','Open tasks ↗')]]))+card('Access & device',links([['W01','Activation status'],['A03','Inspect role design in admin']])+note('Switching applications is a prototype navigation feature, not a production authorization model.'));
default:throw Error('Missing worker route '+id);
}}
function catalogDraftForm(label){return `<div class="split">${primaryForm('Product and variant',field('draft-title','Product title',state.draft.title,'text','required')+`<div class="form-grid">${field('draft-sku','SKU',state.draft.sku,'text','required')}${field('draft-moq','Wholesale MOQ',state.draft.moq,'number','required min="1" max="100000"')}${field('draft-pack','Pack multiple',state.draft.pack,'number','required min="1" max="100000"')}${field('draft-cost','Supplier unit cost (NGN) · staff only',state.draft.cost,'number','required min="1" max="10000000"')}</div>`+note('Supplier cost stays private. Selling prices and publication need reviewer approval.'),"submitCatalogDraft()",label)}${card('Review status',row('Draft',badge(state.draftSubmitted?'Submitted':'Editing','warn'))+row('Catalog review',badge(state.catalogStatus,state.catalogStatus==='Published'?'':'warn'))+timeline([['Worker draft','Verify supplier facts and product attributes.'],['Independent review','Content rights, variants and price policy.'],['Publication','Only approved versions become customer-visible.']])+link('A08','Open admin catalog review →'))}</div>`;}
function submitCatalogDraft(){const moq=Number($('draft-moq').value),pack=Number($('draft-pack').value);if(moq%pack!==0){toast('MOQ must be compatible with the pack multiple in this demo.');return;}state.draft={title:$('draft-title').value,sku:$('draft-sku').value,moq:String(moq),pack:String(pack),cost:$('draft-cost').value};state.draftSubmitted=true;state.catalogStatus='Pending review';record('Chidi submitted catalog draft');toast('Submitted for independent catalog review.');render();}
