const adminDescriptions={A01:'A clear view of sales, fulfillment and the work that needs attention.',A02:'Activate staff only after verification and scoped-role approval.',A03:'Keep every role focused on the work it needs to do.',A04:'One central supplier directory. All relationships managed by ChinaLowCost staff.',A05:'Restricted financial records and independently verified changes.',A06:'Coordinate supplier visits, pickups, deliveries and returns.',A07:'A consistent catalog from multiple offline suppliers.',A08:'Review the exact product version before it becomes customer-visible.',A09:'Retail prices and wholesale quantity tiers, clearly separated.',A10:'Reported stock, confirmed allocations and freshness in one view.',A11:'Manage requests, negotiated prices and quotation versions.',A12:'One order workspace with independent commercial and operational states.',A13:'Purchase against confirmed supplier terms and approved cost limits.',A14:'Match the received units to the purchase order and inspection record.',A15:'Prepare, hand over and follow each shipment.',A16:'Keep exceptions visible until the customer’s resolution is clear.',A17:'Verify actual funds and resolve unmatched payment events.',A18:'Separate worker collection from verified finance handover.',A19:'Review refundable amounts and approve independently.',A20:'Match supplier obligations and approved payments.',A21:'Track returns, inspections, customer resolutions and supplier recovery.',A22:'Customer context with scoped support access.',A23:'Conversations, templates and delivery states for the official business channel.',A24:'Review product stories and connect them to approved SKUs.',A25:'Review AI suggestions and evaluate quality before rollout.',A26:'Actions require a different approver from the requester.',A27:'Visibility into sales, contribution, cash and liabilities.',A28:'Explicit policies and limits for a controlled pilot.',A29:'Inspect who changed what and why.',A30:'Monitor external services and work through failed events.'};
function chart(){const vals=[35,52,44,75,63,92,80];return `<div class="chart" role="img" aria-label="Illustrative weekly sales bar chart: 35, 52, 44, 75, 63, 92 and 80 sample units">${vals.map((v,i)=>`<div style="height:${v}%"><small>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</small></div>`).join('')}</div>`;}
function approveDemo(kind,requester){if(state.staffActor===requester){toast('Self-approval blocked. Choose an independent sample reviewer.');return;}if(state.staffActor!=='Manager'){toast('This sample reviewer lacks approval authority. Switch to Manager.');return;}if(kind==='catalog'&&(!state.consent||!state.draftSubmitted)){toast('A submitted draft and supplier consent are required first.');return;}if(kind==='staff')state.staffStatus='Active';else if(kind==='catalog')state.catalogStatus='Published';else if(!state.approvals.includes(kind))state.approvals.push(kind);record('Independent sample approval: '+kind);toast('Approved in demo by '+state.staffActor+'. No external action performed.');render();}
function rejectDemo(kind){if(state.staffActor!=='Manager'){toast('Only the independent Manager can reject in this demo.');return;}openActionForm('Request correction / reject',[['Reason','Further verification required']],kind==='staff'?'Staff request rejected':'Catalog correction requested',()=>{if(kind==='staff')state.staffStatus='Rejected';if(kind==='catalog')state.catalogStatus='Correction requested';});}
function saveInspection(){const accepted=Number($('accepted-qty').value),rejected=Number($('rejected-qty').value);if(!Number.isInteger(accepted)||!Number.isInteger(rejected)||accepted+rejected!==30){toast('Accepted plus rejected must equal 30 expected units.');return;}if(accepted!==30){record('Partial inspection discrepancy recorded');toast('Discrepancy recorded. Resolve rejected units before the full sample pickup.');return;}state.inspection=true;record('Worker accepted 30 sample units after inspection');toast('Inspection saved. Continue with pickup.');go('W08');}
function simulateFinanceVerify(){if(!state.cart.length){toast('Use customer checkout to create a demo payment first.');return;}simulatePayment();}
function openSupplier(){openModal('Example Lagos Trading',row('Premises','Sample Lagos warehouse')+row('Categories','Electronics')+row('Terms','Payment at accepted pickup')+row('Portal access','None · staff-managed relationship')+note('Photographs and videos require recorded supplier permission.')+links([['A06','Schedule a visit'],['A05','Finance profile'],['A20','Supplier payables']]));}
function openModal(title,body){const modal=$('modal');modal.innerHTML=`<div class="dialog-head"><h2 id="modal-title">${title}</h2>${button('Close',"$('modal').close()",'secondary')}</div>${body}`;if(!modal.open)modal.showModal();}
function openActionForm(title,fields,message,after){window.currentModalAction=()=>{after?.();record(message);$('modal').close();toast(message+'. Demo record only.');render();};openModal(title,`<form onsubmit="event.preventDefault();window.currentModalAction()">${fields.map(([label,value],i)=>field('modal-field-'+i,label,value,'text','required')).join('')}${note('This action records a sample request locally. No external system is changed.')}<div class="form-actions"><button type="submit">Save demo record</button></div></form>`);}
function openPageMap(){openModal('Explore all 66 application pages',`<p>21 customer · 15 worker · 30 admin pages. Select any page to inspect its layout and sample interactions.</p><label for="page-map-query">Find a page</label><input id="page-map-query" placeholder="Search tracking, catalog, cash, approval…" oninput="filterPageMap(this.value)"><div class="screen-map" id="page-map">${PAGES.map(p=>`<a href="#${p.ID}" onclick="$('modal').close()" data-search="${esc((p.ID+' '+p.Application+' '+p.Screen).toLowerCase())}"><strong>${p.ID} · ${esc(navLabel(p))}</strong><small>${p.Application} · ${esc(p['Primary action'])}</small></a>`).join('')}</div>`);}
function filterPageMap(term){document.querySelectorAll('#page-map a').forEach(a=>a.hidden=!a.dataset.search.includes(term.toLowerCase()));}
function resetDemo(){openModal('Reset this sample workspace?',`<p>This clears only this prototype’s locally saved cart, quotations, messages and demo workflow actions.</p><div class="actions">${button('Reset sample data',"state=initialState();persist();localImage='';scenario='normal';$('modal').close();render();toast('Sample workspace reset.')",'danger')}${button('Keep exploring',"$('modal').close()",'secondary')}</div>`);}
function downloadBlob(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample document prepared for download.');}
function simplePDF(lines){const clean=s=>String(s).replace(/[^\x20-\x7e]/g,' ').replace(/[\\()]/g,'\\$&');const stream='BT /F1 18 Tf 48 790 Td ('+clean(lines[0])+') Tj /F1 10 Tf '+lines.slice(1).map(s=>'0 -22 Td ('+clean(s)+') Tj').join(' ')+' ET';const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`];let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=(i+1)+' 0 obj\n'+o+'\nendobj\n';});const start=pdf.length;pdf+='xref\n0 6\n0000000000 65535 f \n'+offsets.slice(1).map(o=>String(o).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+start+'\n%%EOF';return pdf;}
function downloadDocument(kind){const q=state.quote;let lines;if(kind==='quote'){if(!q){toast('Create a quotation first.');return;}lines=['ChinaLowCost - SAMPLE QUOTATION','Not a binding offer. Interactive prototype document.',q.id+' | Version '+q.version,'Customer: Ada Home Store (sample)','Product: '+q.name+' | SKU '+q.sku,'Variant: '+products.find(p=>p.id===q.sku).variant+' | Unit basis: one unit','MOQ 10 | Pack multiple 5 | Quantity '+q.qty,'Unit price: NGN '+q.rate.toLocaleString('en-GB'),'Goods subtotal: NGN '+(q.qty*q.rate).toLocaleString('en-GB'),'Delivery (sample): NGN '+q.delivery.toLocaleString('en-GB'),'Tax: not configured for demo','Total: NGN '+(q.qty*q.rate+q.delivery).toLocaleString('en-GB'),'Issued: '+new Date(q.issued).toISOString(),'Valid until: '+new Date(q.expires).toISOString(),'Availability and final delivery require staff confirmation.','No stock is reserved. No funds have been collected.'];}else{const current=kind==='receipt-current';lines=['ChinaLowCost - SAMPLE RECEIPT','Not a real transaction receipt. Prototype only.','Order: '+(current?'CLC-DEMO-001':'CLC-DEMO-000'),'Customer: Ada (sample)','Amount: NGN '+(current?(state.orderSnapshot?.total??totals().total):53000).toLocaleString('en-GB'),'Status: '+(current?'Simulated verified payment':'Historical sample payment'),'No real money was collected through this prototype.'];}downloadBlob(kind==='quote'?q.id+'-v'+q.version+'.pdf':'ChinaLowCost-Sample-Receipt.pdf',simplePDF(lines),'application/pdf');}
function downloadLedger(){downloadBlob('ChinaLowCost-Sample-Ledger.csv','Account,Debit_NGN,Credit_NGN\nCash or provider clearing,228000,0\nGoods sales,0,220000\nDelivery collected,0,8000\n','text/csv;charset=utf-8');}
window.addEventListener('hashchange',()=>{scenario='normal';render();window.scrollTo({top:0,behavior:'auto'});$('page-title')?.focus({preventScroll:true});});
document.addEventListener('click',e=>{if(e.target.closest?.('#modal a[href^="#"]'))$('modal').close();});
